function report=buildV4R14FormalReportA()
root=v4SetupPaths();base=fullfile(root,'results','formal','track_a','R14-dual-hypothesis');rows=cell(20,12);
for ci=1:2,for si=1:10,index=(ci-1)*10+si;snr=-31+si;x=load(fullfile(base,sprintf('case_%d',ci),sprintf('snr_%+03d',snr),'formal_cell.mat'),'formalCell');f=x.formalCell;s=f.state;paper=double(s.symbolErrors(:,3));stage=double(s.symbolErrors(:,4));d=(stage-paper)/23;stream=RandStream('mt19937ar','Seed',1000000000+ci*100+si);draw=zeros(10000,1);for chunk=1:100,idx=randi(stream,20000,20000,100);draw((chunk-1)*100+(1:100))=mean(d(idx),1).';end;b=prctile(draw,[2.5 97.5]);paperSer=sum(paper)/(20000*23);stageSer=sum(stage)/(20000*23);rows(index,:)={ci,f.caseStartTimeSec,snr,20000,sum(paper),sum(stage),paperSer,stageSer,stageSer-paperSer,b(1),b(2),stageSer<paperSer};end,end
summary=cell2table(rows,'VariableNames',{'caseIndex','caseStartTimeSec','snrDb','pairedPackets','paperErrors','stageErrors','paperSer','stageSer','deltaSer','lower95','upper95','stageBetter'});report=struct('status','PASS','algorithmVersion','Stage55-A-causal-dual-hypothesis-v11','algorithmSignature','c467ac3dee4f816aafc56b59d37030631e4be5b22eecc7d4f11d88f0a66cd8c9','totalPairedPackets',400000,'bootstrapDraws',10000,'summary',summary,'stageBetterAllPoints',all(summary.stageBetter),'ciBelowZeroAllPoints',all(summary.upper95<0));out=fullfile(root,'results','reports');save(fullfile(out,'R14_EXPERIMENT_A_REPORT_DATA.mat'),'report','-v7.3');writetable(summary,fullfile(out,'R14_EXPERIMENT_A_FORMAL_SUMMARY.csv'));write(fullfile(out,'R14_EXPERIMENT_A_REPORT.md'),sprintf('# R14 Experiment A formal report\n\nFixed paired packets: 400000; bootstrap draws: 10000 per point.\n\nStage55 lower SER at all points: `%d`. CI below zero at all points: `%d`.\n\nNo experiment condition or Paper code changed.\n',report.stageBetterAllPoints,report.ciBelowZeroAllPoints));
end
function write(path,text),f=fopen(path,'w','n','UTF-8');cl=onCleanup(@()fclose(f));fprintf(f,'%s\n',text);clear cl,end
